-- Shared vocabulary for this clinic database; contains no patient information.
create table public.emr_descriptors (
 id text primary key default gen_random_uuid()::text check (length(id) between 1 and 80),
 kind text not null check (kind in ('strength','challenge')),
 domain text not null check (length(btrim(domain)) between 1 and 120),
 label text not null check (length(btrim(label)) between 1 and 500),
 active boolean not null default true,
 revision integer not null default 1 check (revision > 0),
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(),
 updated_by uuid references auth.users(id)
);
create unique index emr_descriptors_unique_wording on public.emr_descriptors(kind,lower(btrim(label)));
create table public.emr_descriptor_versions (
 id bigint generated always as identity primary key,
 descriptor_id text not null references public.emr_descriptors(id),
 revision integer not null,
 snapshot jsonb not null,
 changed_at timestamptz not null default now(),
 changed_by uuid references auth.users(id),
 unique(descriptor_id,revision)
);
create function private.prepare_emr_descriptor() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if TG_OP='UPDATE' then
  if new.id is distinct from old.id or new.created_at is distinct from old.created_at then raise exception 'Descriptor identity is immutable'; end if;
  new.revision:=old.revision+1;
 else new.revision:=1;
 end if;
 new.label:=btrim(new.label); new.domain:=btrim(new.domain);
 new.updated_at:=clock_timestamp(); new.updated_by:=auth.uid(); return new;
end; $$;
-- A private trigger alone can append audit snapshots; callers cannot rewrite history.
create function private.audit_emr_descriptor() returns trigger language plpgsql security definer set search_path='' as $$
begin
 values(new.id,new.revision,to_jsonb(new),auth.uid()); return new;
end; $$;
revoke all on function private.prepare_emr_descriptor(),private.audit_emr_descriptor() from public,anon,authenticated;
create trigger prepare_emr_descriptor before insert or update on public.emr_descriptors for each row execute function private.prepare_emr_descriptor();
create trigger audit_emr_descriptor after insert or update on public.emr_descriptors for each row execute function private.audit_emr_descriptor();
alter table public.emr_descriptors enable row level security;
alter table public.emr_descriptor_versions enable row level security;
revoke all on public.emr_descriptors,public.emr_descriptor_versions from public,anon,authenticated;
grant select,insert,update on public.emr_descriptors to authenticated;
grant select on public.emr_descriptor_versions to authenticated;
create policy descriptor_admin_read on public.emr_descriptors for select to authenticated using ((select private.current_user_is_admin()) and (select private.patient_secure_session()));
create policy descriptor_admin_add on public.emr_descriptors for insert to authenticated with check ((select private.current_user_is_admin()) and (select private.patient_secure_session()));
create policy descriptor_admin_edit on public.emr_descriptors for update to authenticated using ((select private.current_user_is_admin()) and (select private.patient_secure_session())) with check ((select private.current_user_is_admin()) and (select private.patient_secure_session()));
create policy descriptor_admin_history on public.emr_descriptor_versions for select to authenticated using ((select private.current_user_is_admin()) and (select private.patient_secure_session()));
create index emr_descriptors_actor_idx on public.emr_descriptors(updated_by);
create index emr_descriptor_versions_actor_idx on public.emr_descriptor_versions(changed_by);

